export const BODY: string = "\n<p>BMP اور JPG دونوں پرانے Windows دور کے فارمیٹ ہیں، مگر وہ شاید ہی زیادہ مختلف ہو سکتے ہیں۔ BMP اسکرین شاٹ 6MB کا ہوتا ہے، جبکہ وہی تصویر JPG میں 500KB کی ہوتی ہے، بغیر نظر آنے والے فرق کے۔</p>\n<p>فرق کمپریشن ہے۔ BMP بمشکل کمپریس کرتا ہے، جبکہ JPG جارحانہ کمپریس کرنے کے لیے بنایا گیا تھا، اور یہ واحد ڈیزائن انتخاب پورے سائز فرق کی وضاحت کرتا ہے۔</p>\n<p>اس موازنے میں بتایا گیا ہے کہ BMP فائلیں اتنی بڑی کیوں ہوتی ہیں، JPG کتنا بچاتا ہے، اور ہر فارمیٹ کا کردار کب باقی رہتا ہے۔</p>\n<h2 id=\"bmp-at-a-glance\">BMP ایک نظر میں</h2>\n<p>BMP Windows کا مقامی تصویری فارمیٹ ہے، جو 1990 کی دہائی سے چلا آ رہا ہے۔ یہ ہر پکسل کو بالکل محفوظ کرتا ہے، بہت کم یا بغیر کمپریشن کے، جو اسے سادہ اور تیز بناتا ہے۔</p>\n<p>یہ فارمیٹ اس وقت ڈیزائن کیا گیا تھا جب پروسیسر سست تھے۔ پکسلز کو خام محفوظ کرنے کا مطلب تھا کہ کمپیوٹر انہیں فوراً دکھا سکتا تھا، بغیر ڈی کمپریس کرنے میں وقت گزارے۔</p>\n<p>BMP کئی رنگ گہرائی سپورٹ کرتا ہے، 1 بٹ سیاہ سفید سے لے کر 24 بٹ مکمل رنگ تک۔ پرانی فائلیں 8 بٹ پیلیٹ استعمال کر سکتی ہیں، جبکہ نئی عام طور پر 24 بٹ ہوتی ہیں۔</p>\n<p>یہ فارمیٹ اب بھی پرانے Windows سافٹ ویئر، اسکینر، اور کچھ ڈیجیٹل کیمروں سے بنتا ہے۔ یہ پرانا فارمیٹ ہے، مگر یہ غائب نہیں ہوا۔</p>\n<h2 id=\"jpg-at-a-glance\">JPG ایک نظر میں</h2>\n<p>JPG 1992 کا لاسی فارمیٹ ہے، جو تصاویر کے لیے ڈیزائن کیا گیا تھا۔ یہ فائلیں چھوٹی کرنے کے لیے تفصیل ضائع کرتا ہے، اور یہ کام اتنا اچھا کرتا ہے کہ تین دہائیوں سے زندہ ہے۔</p>\n<p>دنیا کا ہر ڈیوائس، براؤزر، پرنٹر اور اپ لوڈ فارم JPG کھول سکتا ہے۔ کوئی مرکزی سسٹم اسے مسترد نہیں کرتا، اور کبھی نہیں کیا۔</p>\n<p>JPG صرف 8 بٹ رنگ سپورٹ کرتا ہے اور شفافیت نہیں۔ JPG پکسلز کا فلیٹ مستطیل ہوتا ہے، جو ایک ہی وقت میں سادہ، قابلِ اعتماد اور محدود ہے۔</p>\n<p>فارمیٹ کی کمپریشن اس کی نمایاں خصوصیت ہے۔ یہ پکسلز کو بلاکس میں گروپ کرتا ہے اور ہر بلاک کے اندر رنگ کو سادہ کرتا ہے، اسی لیے JPG فائلیں اتنی چھوٹی ہوتی ہیں۔</p>\n<h2 id=\"why-bmp-is-large\">BMP فائلیں اتنی بڑی کیوں ہوتی ہیں</h2>\n<p>BMP فائل ہر پکسل کو الگ محفوظ کرتی ہے۔ 24 بٹ رنگ پر 1920 بائی 1080 اسکرین شاٹ میں بیس لاکھ سے زیادہ پکسل ہوتے ہیں، اور ہر ایک کو تین بائٹ چاہیے ہوتے ہیں، جو کل 6MB سے زیادہ بنتے ہیں۔</p>\n<p>اسٹوریج میں کوئی چالاکی نہیں۔ سفید پس منظر جسے JPG چند بائٹ میں محفوظ کرتا ہے وہ BMP میں ہزاروں بائٹ لیتا ہے، کیونکہ ہر سفید پکسل الگ لکھا جاتا ہے۔</p>\n<p>ہیڈر کچھ اور بڑھاتے ہیں۔ BMP ہیڈر ابعاد، رنگ گہرائی، اور پیلیٹ بیان کرتا ہے، مگر یہ پکسل ڈیٹا کے مقابلے میں چھوٹا ہوتا ہے۔</p>\n<p>کچھ BMP فائلیں رن لینتھ کمپریشن استعمال کرتی ہیں، جو سادہ تصاویر کے لیے کچھ مدد کرتی ہے۔ زیادہ تر BMP فائلیں، مگر، بغیر کسی کمپریشن کے خام محفوظ ہوتی ہیں۔</p>\n<h2 id=\"how-much-jpg-saves\">JPG واقعی کتنا بچاتا ہے</h2>\n<p>6MB BMP اسکرین شاٹ 85 فیصد کوالٹی پر 500KB JPG بن جاتا ہے۔ یہ 92 فیصد بچت ہے، اور تصویر پھر بھی صاف لگتی ہے۔</p>\n<p>10MB اسکین شدہ BMP اسی سیٹنگ پر 300KB JPG بن جاتا ہے۔ یہ 97 فیصد بچت ہے، کیونکہ اسکین زیادہ تر گہرے متن والا سفید کاغذ ہوتے ہیں۔</p>\n<p>20MB BMP تصویر 85 فیصد کوالٹی پر 1.5MB JPG بن جاتی ہے۔ یہ 92 فیصد بچت ہے، اور تصویر پھر بھی اچھی لگتی ہے۔</p>\n<p>سادہ گرافکس سب سے کم بچاتے ہیں۔ کم رنگوں والا فلیٹ آئیکن صرف آدھا سکڑ سکتا ہے، کیونکہ BMP سادہ تصاویر کو پہلے سے نسبتاً مؤثر طریقے سے محفوظ کرتا ہے۔</p>\n<h2 id=\"quality-compared\">تصویری کوالٹی: معقول سیٹنگ پر برابر</h2>\n<p>85 سے 90 فیصد کوالٹی پر JPG عام دیکھنے کے سائز میں اس BMP جیسا ہی لگتا ہے جس سے وہ آیا تھا۔ ضائع شدہ تفصیل انسانی آنکھ کو نظر نہیں آتی۔</p>\n<p>100 فیصد کوالٹی پر JPG پکسل سطح پر بھی BMP کے تقریباً ایک جیسا ہوتا ہے۔ فائل پھر بھی کہیں چھوٹی ہوتی ہے، کیونکہ JPG کمپریشن اعلیٰ سیٹنگ پر بھی مؤثر ہوتی ہے۔</p>\n<p>کم کوالٹی پر فرق ظاہر ہوتا ہے۔ 50 فیصد پر JPG بلاکی خرابیاں اور نرم متن دکھاتا ہے، جبکہ BMP کامل رہتا ہے، کیونکہ یہ کبھی کچھ ضائع نہیں کرتا۔</p>\n<p>روزمرہ استعمال کے لیے کوالٹی فیصلہ کن عنصر نہیں۔ دونوں فارمیٹ معقول سیٹنگ پر اچھے لگتے ہیں، اور انتخاب سائز اور مطابقت پر آتا ہے۔</p>\n<h2 id=\"colour-depth-compared\">رنگ گہرائی کا موازنہ</h2>\n<p>24 بٹ BMP اور JPG دونوں 24 بٹ رنگ استعمال کرتے ہیں، اور لاکھوں رنگ دستیاب ہوتے ہیں۔ ان کے درمیان تبدیلی رنگ حد کو بالکل محفوظ رکھتی ہے۔</p>\n<p>8 بٹ BMP 256 رنگوں کی پیلیٹ استعمال کرتا ہے۔ اسے JPG میں بدلنے سے پیلیٹ عام RGB رنگوں میں پھیل جاتی ہے، اور تصویر ایک جیسی لگتی ہے۔</p>\n<p>1 بٹ BMP صرف سیاہ سفید رکھتا ہے۔ اسے JPG میں بدلنے سے وہی پکسل والی سیاہ سفید تصویر بنتی ہے، سائز کے حصے پر۔</p>\n<p>رنگ گہرائی شاذ و نادر ہی فارمیٹ انتخاب طے کرتی ہے۔ سائز فرق اتنا بڑا ہے کہ JPG تقریباً ہر صورت میں ڈیلیوری کے لیے جیتتا ہے، چاہے گہرائی کچھ بھی ہو۔</p>\n<h2 id=\"transparency-compared\">شفافیت: کسی بھی فارمیٹ میں نہیں</h2>\n<p>معیاری BMP فائلیں شفافیت سپورٹ نہیں کرتیں۔ ہر پکسل کا ٹھوس رنگ ہوتا ہے، اور شفاف جگہوں کے لیے کوئی الفا چینل نہیں ہوتا۔</p>\n<p>JPG بھی شفافیت سپورٹ نہیں کرتا۔ یہ پکسلز کا فلیٹ مستطیل ہوتا ہے، جس میں شفاف حصے محفوظ کرنے کا کوئی طریقہ نہیں۔</p>\n<p>اس لیے BMP کو JPG میں بدلنے سے شفافیت پر کچھ نہیں کھوتا۔ تصویر پہلے غیر شفاف تھی، اور بعد میں بھی غیر شفاف رہتی ہے، بغیر نظر آنے والی تبدیلی کے۔</p>\n<p>اگر آپ کو شفافیت چاہیے تو کوئی بھی فارمیٹ جواب نہیں۔ PNG یا WebP استعمال کریں، جو دونوں الفا چینل محفوظ کرتے ہیں اور شفاف جگہوں کو شفاف رکھتے ہیں۔</p>\n<h2 id=\"compatibility-compared\">مطابقت: JPG مکمل جیتتا ہے</h2>\n<p>JPG ہر ڈیوائس، ہر آپریٹنگ سسٹم، ہر براؤزر، اور ہر اپ لوڈ فارم پر کھلتا ہے۔ کوئی مرکزی سسٹم JPG مسترد نہیں کرتا۔</p>\n<p>BMP Windows پر مقامی طور پر کھلتا ہے، مگر کہیں اور سپورٹ ٹکڑوں میں ہے۔ Mac، فون، اور ویب براؤزر BMP دکھا سکتے ہیں، مگر بہت سے اوزار اور فارم اسے مسترد کرتے ہیں۔</p>\n<p>ای میل کلائنٹ اکثر BMP اٹیچمنٹ کو بہت بڑا کہہ کر بلاک کرتے ہیں۔ 6MB BMP بہت سی اٹیچمنٹ حدوں سے تجاوز کرتا ہے، جبکہ 500KB JPG ورژن گزر جاتا ہے۔</p>\n<p>ویب سائٹس BMP اپ لوڈ شاذ و نادر قبول کرتی ہیں۔ ویب صفحے پر BMP تصویر آہستہ لوڈ ہوتی ہے اور کچھ براؤزرز میں بالکل دکھائی نہیں دیتی۔</p>\n<h2 id=\"when-to-use-bmp\">BMP کب اب بھی معنی رکھتا ہے</h2>\n<p>BMP پرانے Windows سافٹ ویئر کے اندر معنی رکھتا ہے جو اسے مقامی طور پر بناتا ہے۔ پرانی ایپلیکیشن صرف BMP محفوظ کر سکتی ہے، اور تبدیل کرنا الگ مرحلہ ہوتا ہے، اس کا حصہ نہیں۔</p>\n<p>BMP ایڈیٹنگ کے دوران درمیانی فارمیٹ کے طور پر معنی رکھتا ہے۔ کچھ پرانے اوزار اندرونی طور پر BMP سے کام کرتے ہیں، کیونکہ خام پکسلز کو بدلنا تیز ہوتا ہے۔</p>\n<p>BMP شاذ و نادر صورتوں میں آرکائیو ماسٹر کے طور پر معنی رکھتا ہے۔ لاس لیس BMP پکسلز کی مکمل کاپی ہوتا ہے، حالانکہ PNG بہتر آرکائیو فارمیٹ ہے، کیونکہ یہ بھی لاس لیس ہے اور کہیں چھوٹا ہے۔</p>\n<p>زیادہ تر لوگوں کے لیے BMP صرف ماخذ فارمیٹ کے طور پر معنی رکھتا ہے۔ جس لمحے یہ اس پروگرام سے باہر نکلے جس نے اسے بنایا تھا، اسے JPG یا PNG میں بدلیں۔</p>\n<h2 id=\"when-to-use-jpg\">JPG کب واضح جیتتا ہے</h2>\n<p>شیئرنگ، ای میلنگ، اور اپ لوڈنگ کے لیے JPG استعمال کریں۔ چھوٹی فائلیں تیزی سے بھیجی جاتی ہیں، حدوں سے ٹکرائے بغیر اپ لوڈ ہوتی ہیں، اور ہر جگہ کھلتی ہیں۔</p>\n<p>ویب سائٹس کے لیے JPG استعمال کریں۔ ویب صفحے پر BMP تصویر سست اور اکثر غیر سپورٹ شدہ ہوتی ہے، جبکہ JPG تیزی سے لوڈ ہوتی ہے اور ہر براؤزر میں دکھائی دیتی ہے۔</p>\n<p>اسکین اور اسکرین شاٹس آرکائیو کرنے کے لیے JPG استعمال کریں۔ BMP اسکین کا فولڈر جو ڈرائیو بھرتا تھا وہ JPG کا فولڈر بن جاتا ہے جو USB اسٹک پر فٹ ہوتا ہے۔</p>\n<p>ہر اس تصویر کے لیے JPG استعمال کریں جو Windows سے باہر کام کرنی چاہیے۔ جس لمحے فائل Windows دنیا سے باہر نکلے، BMP ذمہ داری بن جاتا ہے اور JPG محفوظ انتخاب بن جاتا ہے۔</p>\n<h2 id=\"converting-strategy\">پرانی BMP فائلوں کے لیے حکمت عملی</h2>\n<p>BMP فائلوں کو ملتے ہی JPG میں بدلیں۔ تبدیلی سیکنڈوں میں ہوتی ہے، بچت بہت بڑی ہوتی ہے، اور نتیجہ ہر جگہ کام کرتا ہے۔</p>\n<p>اگر وہ اہمیت رکھتی ہوں تو BMP اصل کو آرکائیو فولڈر میں رکھیں۔ وہ ماسٹر ہیں، اور اگر آپ کو بعد میں مختلف فارمیٹ چاہیے ہو تو آپ انہیں ہمیشہ دوبارہ بدل سکتے ہیں۔</p>\n<p>85 فیصد کوالٹی کو ڈیفالٹ رکھیں۔ یہ متن کو پڑھنے کے قابل اور تصاویر کو صاف رکھتی ہے، جبکہ فائلوں کو 90 فیصد یا اس سے زیادہ سکڑتی ہے۔</p>\n<p>پورے آرکائیو کے لیے بیچ میں بدلیں۔ <a href=\"/ur/bmp-ko-jpg-mein-convert-karein/\">BMP to JPG converter</a> اسکین کے فولڈر سنبھالتا ہے، اور بیچ خلاصہ کل بچت دکھاتا ہے۔</p>\n<h2 id=\"verdict\">فیصلہ: کون سا فارمیٹ جیتتا ہے؟</h2>\n<p>JPG سائز، مطابقت، اور عملیت میں جیتتا ہے۔ یہ 90 فیصد یا اس سے زیادہ چھوٹا ہوتا ہے، یہ ہر جگہ کھلتا ہے، اور معقول کوالٹی سیٹنگ پر ایک جیسا لگتا ہے۔</p>\n<p>BMP صرف سادگی اور لاس لیس اسٹوریج میں جیتتا ہے۔ یہ پکسلز کی مکمل کاپی ہوتا ہے، جو آرکائیو ماسٹر اور اسے بنانے والے پرانے سافٹ ویئر کے لیے اہمیت رکھتا ہے۔</p>\n<p>تقریباً ہر حقیقی استعمال کے لیے JPG درست فارمیٹ ہے۔ BMP ماخذ فارمیٹ ہے، ڈیلیوری فارمیٹ نہیں، اور اسے JPG میں بدلنا تصویر کام میں سب سے آسان جیتوں میں سے ایک ہے۔</p>\n<p>نمبر کہانی بتاتے ہیں: 6MB فائل 500KB بن جاتی ہے، 10MB اسکین 300KB بن جاتا ہے، اور کچھ بھی نظر آنے والا نہیں کھوتا۔ جلد بدلیں، اکثر بدلیں، اور اصل رکھیں۔</p>\n<h2 id=\"bmp-in-medical-imaging\">طبی امیجنگ میں BMP</h2>\n<p>طبی امیجنگ سافٹ ویئر کبھی کبھی اسکین کو BMP کے طور پر محفوظ کرتا ہے، کیونکہ فارمیٹ سادہ اور لاس لیس ہے۔ ایک اسکین دسیوں میگا بائٹ کا ہو سکتا ہے، جو اسٹوریج کو مشکل بنا دیتا ہے۔</p>\n<p>شیئرنگ کے لیے اسکین کو 90 فیصد کوالٹی پر JPG میں بدلیں۔ تصاویر جائزے کے لیے کافی تیز رہتی ہیں، جبکہ فائلیں ڈرامائی طور پر سکڑ جاتی ہیں اور آسانی سے بھیجی جاتی ہیں۔</p>\n<p>تشخیص کے لیے کبھی لاسی کاپی پر انحصار نہ کریں۔ کمپریس شدہ اسکین تفصیل چھپا یا ایجاد کر سکتا ہے، اس لیے اصل BMP یا لاس لیس PNG ہی طبی کام کے لیے محفوظ ورژن ہے۔</p>\n<p>اصل BMP فائلوں کو محفوظ آرکائیو میں رکھیں۔ طبی ریکارڈ کی قانونی برقرار رکھنے کی ضروریات ہوتی ہیں، اور اصل ثابت کرتے ہیں کہ تصاویر وفاداری سے بدلی گئی تھیں۔</p>\n<p>تصاویر کو واضح ناموں اور تاریخوں کے ساتھ محفوظ کریں۔ scan-2026-11-17.bmp نامی فائل سالوں بعد طبی ریکارڈ میں مفید ہوتی ہے، جبکہ image001.bmp نامی فائل نہیں ہوتی۔</p>\n<h2 id=\"bmp-in-industrial-software\">صنعتی سافٹ ویئر میں BMP</h2>\n<p>صنعتی سافٹ ویئر، جیسے مشین ویژن اور کوالٹی کنٹرول سسٹم، اکثر تصاویر کو BMP کے طور پر محفوظ کرتے ہیں۔ فارمیٹ سادہ، لکھنے میں تیز، اور سافٹ ویئر کے لیے پڑھنے میں آسان ہوتا ہے۔</p>\n<p>ساتھیوں کے ساتھ شیئر کرنے سے پہلے تصاویر کو JPG میں بدلیں۔ 20MB BMP اٹیچمنٹ زیادہ تر ای میل حدوں سے تجاوز کرتا ہے، جبکہ 500KB JPG ورژن فوراً بھیجا جاتا ہے۔</p>\n<p>کوالٹی کنٹرول آرکائیو کے لیے BMP اصل رکھیں۔ لاس لیس فائلیں ثبوت ہوتی ہیں، جبکہ JPG کاپیاں رپورٹ اور پریزنٹیشن کے لیے ہوتی ہیں۔</p>\n<p>اگر حجم زیادہ ہو تو تبدیلی کو خودکار کریں۔ جو مشین روزانہ سینکڑوں تصاویر بناتی ہے اسے بیچ عمل چاہیے ہوتا ہے، ہر تصویر کے لیے دستی تبدیلی نہیں۔</p>\n<p>ٹیم کے لیے تبدیلی کی سیٹنگ دستاویز کریں۔ ایک لائن نوٹ ملے ہوئے فارمیٹس میں آہستہ بہاؤ کو روکتا ہے جو ہر صنعتی ورک فلو کو پریشان کرتا ہے۔</p>\n<h2 id=\"storage-costs-bmp\">BMP کی اسٹوریج قیمت</h2>\n<p>BMP فائلیں اسٹوریج میں حقیقی پیسہ لیتی ہیں۔ ہزار 6MB اسکرین شاٹس والے فولڈر کو 6GB ڈسک چاہیے ہوتی ہے، جبکہ وہی فولڈر JPG میں 500MB چاہتا ہے، بارہ گنا فرق۔</p>\n<p>کلاؤڈ اسٹوریج گیگا بائٹ کے حساب سے چارج کرتا ہے، اس لیے BMP آرکائیو JPG آرکائیو سے بارہ گنا زیادہ مہنگا ہوتا ہے۔ آرکائیو بدلنا پہلے مہینے میں اپنی قیمت ادا کر دیتا ہے۔</p>\n<p>بیک اپ بھی قیمت لیتے ہیں۔ BMP آرکائیو بیک اپ ہونے میں بارہ گنا زیادہ وقت لیتا ہے، اور بیک اپ ڈرائیو بارہ گنا تیزی سے بھرتی ہے، جس کا مطلب ہے زیادہ ہارڈ ویئر اور زیادہ وقت۔</p>\n<p>بڑے تصویری آرکائیو والے کاروبار کے لیے بچت نمایاں ہوتی ہے۔ ایک ٹیرا بائٹ BMP فائلیں JPG میں 100GB بن جاتی ہیں، اور سالوں کے نئے کام کے لیے جگہ آزاد ہو جاتی ہے۔</p>\n<p>آرکائیو کو بیچ میں بدلیں، اصل حذف کرنے سے پہلے ہر بیچ کی تصدیق کریں۔ احتیاط والی منتقلی اہم فائلوں کو خطرے میں ڈالے بغیر پیسہ بچاتی ہے۔</p>\n<h2 id=\"bmp-in-old-video-games\">پرانے ویڈیو گیمز میں BMP</h2>\n<p>پرانے ویڈیو گیمز ٹیکسچر اور اسپرائٹ کو BMP فائلوں کے طور پر محفوظ کرتے ہیں، کیونکہ یہ فارمیٹ اس وقت معیار تھا جب گیمز لکھے گئے تھے۔ وہ فائلیں بڑی ہوتی ہیں، اور جدید اوزار انہیں بدلنے کی ضرورت رکھتے ہیں۔</p>\n<p>ایڈیٹنگ کے لیے گیم ٹیکسچر کو PNG میں بدلیں۔ لاس لیس فارمیٹ پکسلز کو بالکل محفوظ رکھتا ہے، جو پکسل آرٹ کے لیے اہمیت رکھتا ہے جہاں ہر پکسل جان بوجھ کر ہوتا ہے۔</p>\n<p>پرانے گیمز کے اسکرین شاٹس شیئر کرنے کے لیے JPG میں بدلیں۔ اسکرین شاٹس 90 فیصد سکڑ جاتے ہیں، اور فورم اور سوشل میڈیا JPG کو مقامی طور پر سنبھالتے ہیں۔</p>\n<p>اہم گیم فائلوں کے لیے BMP اصل رکھیں۔ پرانے گیم پر کام کرنے والے موڈر کو اصل ٹیکسچر چاہیے ہوتے ہیں، جبکہ JPG کاپیاں پیش نظارہ اور اسکرین شاٹس کے لیے ہوتی ہیں۔</p>\n<p>بدلی ہوئی فائلیں شیئر کرتے وقت گیم کے کاپی رائٹ کا احترام کریں۔ ٹیکسچر گیم کے خالقوں کی ملکیت ہوتا ہے، اور فارمیٹ بدلنے سے ملکیت نہیں بدلتی۔</p>\n<h2 id=\"migrating-bmp-archive\">BMP آرکائیو منتقل کرنا</h2>\n<p>BMP آرکائیو منتقل کرنا پروجیکٹ ہے، کام نہیں۔ اسے بیچ میں منصوبہ بنائیں، ایک وقت میں ایک فولڈر، اگلے پر جانے سے پہلے ہر بیچ کی تصدیق کریں۔</p>\n<p>سب سے کم اہم فولڈر سے شروع کریں، کیونکہ وہاں غلطی کم قیمت لیتی ہے۔ کامیاب پہلا بیچ زیادہ اہم فولڈرز کے لیے اعتماد بناتا ہے۔</p>\n<p>ہر بیچ کو 85 فیصد کوالٹی پر بدلیں، پھر فائلوں کا نمونہ تصدیق کریں۔ فی بیچ پانچ فائلوں کی فوری جانچ مسائل کو پھیلنے سے پہلے پکڑتی ہے۔</p>\n<p>پوری منتقلی تصدیق ہونے تک BMP اصل رکھیں۔ انہیں جلد حذف کرنا ان فائلوں کو کھونے کا خطرہ ہے جنہیں دوبارہ نہیں بنایا جا سکتا، جبکہ انہیں رکھنا صرف ڈسک جگہ لیتا ہے۔</p>\n<p>منتقلی کو مختصر لاگ میں دستاویز کریں۔ فی فولڈر ایک لائن، تاریخ اور فائل تعداد کے ساتھ، پروجیکٹ کی کہانی بتاتی ہے اور ثابت کرتی ہے کہ یہ احتیاط سے کیا گیا تھا۔</p>\n<p>ابھی بدلنا چاہتے ہیں؟ <a href=\"/ur/bmp-ko-jpg-mein-convert-karein/\">BMP to JPG tool</a> کھولیں اور اپنی فائلیں ڈالیں۔ مراحل کے لیے <a href=\"/ur/blog/bmp-ko-jpg-mein-kaise-convert-karein/\">How to Convert BMP to JPG</a> پڑھیں، اور عمومی پس منظر کے لیے <a href=\"/ur/blog/bmp-ko-jpg-rehnumai/\">BMP to JPG: Complete Guide</a> دیکھیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ایک ہی تصویر BMP میں JPG کے مقابلے میں کتنی بڑی ہوتی ہے؟","answer":"فرق بہت بڑا ہوتا ہے، کیونکہ BMP ہر پکسل کی مکمل تفصیل بغیر دبائے محفوظ کرتا ہے، جبکہ JPG وہ باریک تفصیل ہٹا دیتا ہے جو آنکھ بمشکل دیکھتی ہے۔ اسی لیے 1920 بائی 1080 اسکرین شاٹ BMP میں 6MB سے زیادہ بنتا ہے اور JPG میں صرف 500KB کے قریب رہ جاتا ہے — یعنی ایک ہی تصویر دونوں فارمیٹ میں دس گنا سے زیادہ فرق رکھ سکتی ہے۔"},{"question":"کیا BMP کو JPG میں بدلنے سے تصویری کوالٹی کم ہوتی ہے؟","answer":"معقول سیٹنگ پر بہت کم۔ 85 سے 90 فیصد کوالٹی پر JPG عام دیکھنے کے سائز میں BMP جیسا ہی لگتا ہے۔ ضائع شدہ تفصیل انسانی آنکھ کو نظر نہیں آتی۔ صرف کم کوالٹی سیٹنگ پر فرق ظاہر ہوتا ہے۔"},{"question":"کیا آرکائیو کے لیے BMP JPG سے بہتر کوالٹی دیتا ہے؟","answer":"BMP لاس لیس ہے، اس لیے یہ مکمل کاپی ہوتا ہے، مگر PNG بہتر آرکائیو فارمیٹ ہے، کیونکہ یہ بھی لاس لیس ہے اور کہیں چھوٹا ہے۔ JPG لاسی ہے، اس لیے یہ ماسٹر کے لیے مثالی نہیں۔ اصل کو BMP یا PNG میں آرکائیو فولڈر میں رکھیں۔"},{"question":"کیا میں BMP کو JPG میں رنگ کھوئے بغیر بدل سکتا ہوں؟","answer":"عملی طور پر ہاں۔ 24 بٹ BMP اور JPG دونوں 24 بٹ رنگ استعمال کرتے ہیں، اس لیے تبدیلی رنگ حد محفوظ رکھتی ہے۔ پرانی 8 بٹ فائلوں میں بہت غیر معمولی پیلیٹ کچھ بدل سکتی ہیں، مگر فرق شاذ و نادر نظر آتا ہے۔"},{"question":"کچھ پروگرام اب بھی تصاویر BMP کے طور پر کیوں محفوظ کرتے ہیں؟","answer":"پرانا Windows سافٹ ویئر BMP کے گرد بنا تھا، کیونکہ سست پروسیسرز پر خام پکسلز پڑھنا اور لکھنا تیز تھا۔ یہ فارمیٹ پرانی ایپلیکیشنز، اسکینر، اور کچھ کیمروں میں برقرار ہے، حالانکہ جدید فارمیٹ بہتر ہیں۔"},{"question":"کیا میں اپنی تمام پرانی BMP فائلوں کو JPG میں بدل دوں؟","answer":"ہاں، ان فائلوں کے لیے جنہیں آپ استعمال، شیئر، یا اپ لوڈ کرتے ہیں، کیونکہ 90 فیصد بچت اور عالمگیر مطابقت اس کے قابل ہیں۔ اگر وہ اہمیت رکھتی ہوں تو BMP اصل کو آرکائیو فولڈر میں رکھیں، کیونکہ JPG کبھی دوبارہ BMP نہیں بن سکتی۔"}];
